import sys
import heapq

data = sys.stdin.read().split()
MOD = 998244353
D, q = int(data[0]), int(data[1])
divs = [d for d in range(1, D + 1) if D % d == 0]
def isprime(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True
def nd(x):
    return sum(1 for d in divs if x % d == 0)
adj = {d: [] for d in divs}
for x in divs:
    for y in divs:
        if x > y and x % y == 0 and isprime(x // y):
            w = sum(1 for t in range(1, x + 1) if x % t == 0 and y % t != 0)
            adj[x].append((y, w))
            adj[y].append((x, w))
def solve(u, v):
    dist = {d: None for d in divs}
    cnt = {d: 0 for d in divs}
    dist[u] = 0
    cnt[u] = 1
    h = [(0, u)]
    done = set()
    while h:
        d0, x = heapq.heappop(h)
        if x in done:
            continue
        done.add(x)
        for y, w in adj[x]:
            nd2 = d0 + w
            if dist[y] is None or nd2 < dist[y]:
                dist[y] = nd2
                cnt[y] = cnt[x]
                heapq.heappush(h, (nd2, y))
            elif nd2 == dist[y]:
                cnt[y] += cnt[x]
    return cnt[v] % MOD
out = []
for i in range(q):
    out.append(solve(int(data[2 + 2 * i]), int(data[3 + 2 * i])))
print('\n'.join(map(str, out)))

